"use client"

import * as React from "react"
import { cn } from "cn"

import { Button } from "@/components/standard/button"

function Sheet({
  className,
  title,
  trigger = "Open sheet",
  children,
}: {
  className?: string
  title: string
  trigger?: string
  children?: React.ReactNode
}) {
  const [open, setOpen] = React.useState(false)

  return (
    <div data-slot="sheet">
      <Button tone="outline" onClick={() => setOpen(true)}>
        {trigger}
      </Button>
      {open ? (
        <div className="fixed inset-0 z-40 bg-black/40" onClick={() => setOpen(false)}>
          <aside
            className={cn(
              "absolute top-0 right-0 flex h-full w-72 flex-col gap-3 border-l border-border bg-background p-4",
              className
            )}
            onClick={(event) => event.stopPropagation()}
          >
            <h2 className="text-sm font-semibold">{title}</h2>
            {children}
            <Button tone="outline" onClick={() => setOpen(false)}>
              Close
            </Button>
          </aside>
        </div>
      ) : null}
    </div>
  )
}

function Toast({
  className,
  children,
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="toast"
      className={cn(
        "rounded-lg border border-border bg-background px-3 py-2 text-sm shadow-md",
        className
      )}
    >
      {children}
    </div>
  )
}

export { Sheet, Toast }
